mapper.select:
SELECT EXISTS(
    SELECT 1
    FROM accounts
    WHERE account_id = #{accountId}
      AND user_id = #{userId}
)

SELECT EXISTS(
    SELECT 1
    FROM securities
    WHERE security_id = #{securityId}
      AND ticker = #{stockCode}
)

SELECT EXISTS(
    SELECT 1
    FROM product_options
    WHERE product_option_id = #{productOptionId}
)

SELECT action_type, asset_type, security_id, stock_code, product_option_id, quantity, action_amount, execution_price, previous_close_price, current_close_price, open_price, high_price, low_price, traded_at FROM ( SELECT security_order.order_type AS action_type, 'SECURITY' AS asset_type, security_order.security_id, security.ticker AS stock_code, NULL AS product_option_id, security_order.quantity, NULL AS action_amount, security_order.executed_price AS execution_price, previous_price.close_price AS previous_close_price, daily_price.close_price AS current_close_price, daily_price.open_price AS open_price, daily_price.high_price AS high_price, daily_price.low_price AS low_price, security_order.executed_at AS traded_at FROM security_orders security_order JOIN securities security ON security.security_id = security_order.security_id LEFT JOIN security_daily_prices daily_price ON daily_price.security_id = security_order.security_id AND daily_price.trade_date = DATE(security_order.executed_at) LEFT JOIN security_daily_prices previous_price ON previous_price.security_id = security_order.security_id AND previous_price.trade_date = ( SELECT MAX(price_history.trade_date) FROM security_daily_prices price_history WHERE price_history.security_id = security_order.security_id AND price_history.trade_date < DATE(security_order.executed_at) ) WHERE security_order.account_id = #{accountId} AND security_order.status = 'FILLED' AND security_order.executed_at IS NOT NULL AND security_order.executed_at < #{tradedAt}
UNION ALL
SELECT product_transaction.type AS action_type, 'PRODUCT' AS asset_type, NULL AS security_id, NULL AS stock_code, holding_product.product_option_id, NULL AS quantity, product_transaction.amount AS action_amount, NULL AS execution_price, NULL AS previous_close_price, NULL AS current_close_price, NULL AS open_price, NULL AS high_price, NULL AS low_price, COALESCE(product_transaction.terminated_at, product_transaction.created_at) AS traded_at FROM product_transactions product_transaction JOIN holding_products holding_product ON holding_product.holding_product_id = product_transaction.holding_product_id WHERE holding_product.account_id = #{accountId} AND product_transaction.status = 'COMPLETED' AND product_transaction.type IN ('SUBSCRIBE', 'TERMINATE', 'MATURITY') AND COALESCE(product_transaction.terminated_at, product_transaction.created_at) < #{tradedAt} ) previous_behavior ORDER BY traded_at DESC
